// ===== Read Message =====
// One item per customer message. Delivery receipts carry no .messages and are dropped.
const out = [];
const digitsOnly = (s) => String(s == null ? '' : s).replace(/\D/g, '');
for (const it of $input.all()) {
  const j = it.json || {};
  const body = (j.body && j.body.entry) ? j.body : (j.entry ? j : null);
  if (!body) continue;
  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      const v = change.value || {};
      const pnid = (v.metadata || {}).phone_number_id;
      if (!pnid) continue;
      const contacts = v.contacts || [];
      for (const m of v.messages || []) {
        const wa = digitsOnly(m.from);
        if (!wa) continue;
        let kind = 'other', id = '', text = '';
        if (m.type === 'text') { kind = 'text'; text = String((m.text || {}).body || '').trim(); }
        else if (m.type === 'interactive') {
          const r = (m.interactive || {}).list_reply || (m.interactive || {}).button_reply;
          if (r) { kind = 'choice'; id = String(r.id || ''); text = String(r.title || ''); }
        } else if (m.type === 'button') {            // quick reply on a reminder template
          kind = 'choice'; id = String((m.button || {}).payload || ''); text = String((m.button || {}).text || '');
        }
        const prof = ((contacts.find((c) => digitsOnly(c.wa_id) === wa) || contacts[0] || {}).profile) || {};
        out.push({ json: { wa_id: wa, phone_number_id: pnid, kind, id, text,
          profile_name: String(prof.name || ''), msg_id: String(m.id || ('gen-' + Date.now() + Math.random())) } });
      }
    }
  }
}
return out;

// ===== This Message =====
// The loop's current message, kept here so every later node can read it. Nodes after an
// HTTP call lose their input, and this node runs on every pass, so it is always current.
const CFG = $('Config').first().json;
const m = $input.first().json;
// One read for everything. Handoffs is written to but never searched, so only its
// header row is fetched - enough to know the column order, without downloading history.
const tabs = ['FAQ', 'AppointmentTypes', 'Owners', 'Pets', 'Sessions', 'Appointments', 'Handoffs'];
const ranges = tabs.map((t) => (t === 'Handoffs' ? 'Handoffs!1:1' : t));
return [{ json: { ...m,
  sheetsUrl: 'https://sheets.googleapis.com/v4/spreadsheets/' + encodeURIComponent(CFG.sheet_id)
    + '/values:batchGet?majorDimension=ROWS&valueRenderOption=FORMATTED_VALUE&'
    + ranges.map((r) => 'ranges=' + encodeURIComponent(r)).join('&'),
  tabs,
} }];

// ===== Assistant Engine =====
// Deterministic router. It never lets the model near an emergency or a medical question,
// and it never lets the model book anything. The model only answers from the FAQ tab.
const CFG = $('Config').first().json;
const m = $('This Message').first().json;
// --- Google Sheets helpers (identical copy in every node that reads the sheet) ---
const S = (v) => (v == null ? '' : String(v));
const digits = (s) => S(s).replace(/\D/g, '');

// values:batchGet returns ragged rows: trailing empty cells are simply missing, and a
// blank line comes back as []. Read by header name and keep the real sheet row number.
function readTables(batch, names) {
  const out = {};
  const vrs = (batch && batch.valueRanges) || [];
  names.forEach((name, i) => {
    const vr = vrs[i] || {};
    const got = S(vr.range).replace(/^'|'?!.*$/g, '');
    if (vr.range && got && got !== name) throw new Error('Sheet order mismatch: expected ' + name + ', got ' + got);
    const rows = vr.values || [];
    const header = (rows[0] || []).map((h) => S(h).trim());
    const recs = [];
    for (let r = 1; r < rows.length; r++) {
      const row = rows[r] || [];
      if (!row.some((c) => S(c).trim() !== '')) continue;
      const rec = { __row: r + 1 };
      header.forEach((h, c) => { if (h) rec[h] = row[c] === undefined ? '' : S(row[c]).trim(); });
      recs.push(rec);
    }
    out[name] = { header, rows: recs };
  });
  return out;
}

// Staff type dates however they like, and Sheets displays them in the sheet's locale.
function parseDate(raw, order, zone) {
  const v = S(raw).trim();
  if (!v) return null;
  let d = null;
  if (/^\d{4}-\d{2}-\d{2}/.test(v)) d = DateTime.fromISO(v.slice(0, 10), { zone });
  else if (/^\d{4,5}(\.\d+)?$/.test(v)) {                          // a raw Sheets serial number
    d = DateTime.fromISO('1899-12-30', { zone }).plus({ days: Math.floor(Number(v)) });
  } else {
    const m = v.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/);
    if (m) {
      const a = +m[1], b = +m[2]; let y = +m[3]; if (y < 100) y += 2000;
      const [day, month] = order === 'MDY' ? [b, a] : [a, b];
      d = DateTime.fromObject({ year: y, month, day }, { zone });
    } else {
      for (const f of ['d LLL yyyy', 'd LLLL yyyy', 'LLL d, yyyy', 'LLLL d, yyyy', 'd-LLL-yyyy']) {
        const t = DateTime.fromFormat(v, f, { zone });
        if (t.isValid) { d = t; break; }
      }
    }
  }
  return d && d.isValid ? d.startOf('day') : null;
}
// --- outcome helpers (identical copy in every node that ends a turn) ---
const clip = (s, n) => (S(s).length > n ? S(s).slice(0, n - 1) + '\u2026' : S(s));
const waBase = (to) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to });
const txt = (to, body) => ({ ...waBase(to), type: 'text', text: { preview_url: false, body: clip(body, 4096) } });
const btns = (to, body, opts) => ({ ...waBase(to), type: 'interactive',
  interactive: { type: 'button', body: { text: clip(body, 1024) },
    action: { buttons: opts.slice(0, 3).map((o) => ({ type: 'reply', reply: { id: clip(o.id, 256), title: clip(o.title, 20) } })) } } });
const lst = (to, body, buttonText, section, rows) => ({ ...waBase(to), type: 'interactive',
  interactive: { type: 'list', body: { text: clip(body, 1024) },
    action: { button: clip(buttonText, 20), sections: [{ title: clip(section, 24),
      rows: rows.slice(0, 10).map((r) => { const o = { id: clip(r.id, 200), title: clip(r.title, 24) };
        if (r.description) o.description = clip(r.description, 72); return o; }) }] } } });
// a list holds ten rows; longer option sets get a "More" row and a page number
function paged(options, page) {
  if (options.length <= 10) return options;
  const start = (page || 0) * 9;
  const rows = options.slice(start, start + 9);
  if (start + 9 < options.length) rows.push({ id: '__more', title: 'More \u25b8', description: 'Show more options' });
  else rows.push({ id: '__first', title: '\u25c2 Back to start', description: 'Show the first options' });
  return rows;
}
// every turn ends here: the reply, the session save, any other sheet writes, any staff alert
function outcome(ctx, state, reply, writes, alert) {
  let saved = JSON.stringify(state || {});
  if (saved.length > 40000 && state && state.slots) {           // a Sheets cell holds 50,000 characters
    saved = JSON.stringify({ ...state, slots: state.dayISO ? { [state.dayISO]: state.slots[state.dayISO] } : {} });
  }
  const sess = { phone: '+' + ctx.phone, state: saved, updated_at: DateTime.now().toUTC().toISO() };
  const first = ctx.sessionRow ? { op: 'update', tab: 'Sessions', row: ctx.sessionRow, record: sess }
                               : { op: 'append', tab: 'Sessions', record: sess };
  return { json: { outcome: true, to: ctx.phone, phone_number_id: ctx.phone_number_id,
    graph_version: ctx.graph_version, token: ctx.token, sheet_id: ctx.sheet_id, headers: ctx.headers,
    reply, silent: reply === null, writes: [first].concat(ctx.pendingWrites || [], writes || []), alert: alert || null } };
}

// If the sheet cannot be read, every customer would look like a stranger and be
// registered again. Say sorry, write nothing, and tell the staff.
const batch = $input.first().json || {};
let T;
try {
  if (batch.error || !Array.isArray(batch.valueRanges)) throw new Error(S((batch.error && batch.error.message) || 'no data returned'));
  T = readTables(batch, m.tabs);
} catch (err) {
  return [{ json: { action: 'reply', outcome: true, to: S(m.wa_id), phone_number_id: m.phone_number_id,
    graph_version: CFG.graph_version || 'v25.0', token: CFG.wa_token, sheet_id: CFG.sheet_id, headers: {},
    reply: txt(S(m.wa_id), 'Sorry - our system is having a moment. Please try again in a few minutes, or call us on '
      + S(CFG.clinic_phone) + '.'),
    writes: [], alert: { title: 'Clinic sheet unreadable', message: S(err.message).slice(0, 300), priority: 1 } } }];
}
const zone = CFG.timezone || 'Europe/London';
const now = DateTime.now().setZone(zone);
const phone = S(m.wa_id);
const input = { kind: m.kind, id: S(m.id), text: S(m.text).trim() };
const low = input.text.toLowerCase();

// ---------- who is this ----------
const owner = T.Owners.rows.find((r) => digits(r.phone) === phone) || null;
const pets = T.Pets.rows.filter((p) => digits(p.owner_phone) === phone);
const sessRec = T.Sessions.rows.find((r) => digits(r.phone) === phone) || null;
const types = T.AppointmentTypes.rows.filter((t) => t.name && !/^(no|false|0)$/i.test(t.active || 'yes'));
const faq = T.FAQ.rows.filter((f) => f.question && f.answer && !/^(no|false|0)$/i.test(f.active || 'yes'));
const upcoming = T.Appointments.rows.filter((a) => digits(a.owner_phone) === phone && /^booked$/i.test(a.status)
  && DateTime.fromISO(a.start, { zone }).isValid && DateTime.fromISO(a.start, { zone }) > now)
  .sort((a, b) => (a.start < b.start ? -1 : 1));

let state = {};
try { state = JSON.parse((sessRec && sessRec.state) || '{}') || {}; } catch (e) { state = {}; }
const updated = sessRec ? DateTime.fromISO(S(sessRec.updated_at)) : null;
if (updated && updated.isValid && now.diff(updated, 'hours').hours > (Number(CFG.session_hours) || 6)) {
  state = { seen: state.seen || [] };                        // idle too long: start fresh
}
state.seen = Array.isArray(state.seen) ? state.seen : [];
if (state.seen.includes(m.msg_id)) return [{ json: { action: 'skip' } }];   // WhatsApp re-delivered this one
state.seen = state.seen.concat([m.msg_id]).slice(-15);

const ctx = {
  phone, phone_number_id: m.phone_number_id, graph_version: CFG.graph_version || 'v25.0', token: CFG.wa_token,
  sheet_id: CFG.sheet_id, calendar_id: CFG.calendar_id, zone,
  headers: Object.fromEntries(Object.entries(T).map(([k, v]) => [k, v.header])),
  sessionRow: sessRec ? sessRec.__row : null,
  owner, pets, types, upcoming, clinic: S(CFG.clinic_name) || 'the clinic',
};
const to = phone;
const first = S((owner && owner.name) || m.profile_name).split(' ')[0];
const hello = first ? 'Hi ' + first + '! ' : 'Hi! ';
const newId = (p) => p + '-' + Math.random().toString(36).slice(2, 8).toUpperCase();
const done = (st, reply, writes, alert) => [{ json: { action: 'reply', ctx, ...outcome(ctx, st, reply, writes, alert).json } }];

// ---------- 1. emergencies never wait, and never reach the model ----------
const EMERGENCY = /\b(not breathing|can'?t breathe|cannot breathe|struggling to breathe|collaps(e|ed|es|ing)|seizures?|having (a )?fits?|convuls\w*|unconscious|unresponsive|hit by a car|run over|poison(ed|ing|ous)?|ate (some |a )?(chocolate|grapes|raisins|rat poison|antifreeze|xylitol|lilies|ibuprofen|paracetamol|onions?)|swallowed (a |some |my |his |her )?(battery|batteries|sock|bone|toy|string|tablets?|pills?|medication)|antifreeze|bleeding (heavily|a lot|badly)|heavy bleeding|won'?t stop bleeding|choking|bloat(ed|ing)?|can'?t stand|cannot stand|paralys\w*|heat ?stroke|giving birth|in labour|can'?t (pee|urinate|wee)|straining to (pee|urinate|wee)|emergency)\b/i;
if (input.kind === 'text' && EMERGENCY.test(low)) {
  const reply = txt(to, '\ud83d\udea8 If your pet is in danger right now, please call us immediately on ' + S(CFG.emergency_phone)
    + '.\n\nOut of hours: ' + S(CFG.out_of_hours || CFG.emergency_phone)
    + '\n\nPlease do not wait for a reply here. I have also alerted the team.');
  const handoff = { handoff_id: newId('H'), phone: '+' + phone, name: (owner && owner.name) || m.profile_name,
    reason: 'EMERGENCY', message: input.text.slice(0, 500), priority: 'emergency', status: 'open', created_at: now.toISO() };
  return done({ ...state, step: 'menu' }, reply, [{ op: 'append', tab: 'Handoffs', record: handoff }],
    { title: 'EMERGENCY - ' + (handoff.name || '+' + phone), message: '+' + phone + ': ' + input.text.slice(0, 300), priority: 1 });
}

// ---------- 2. medical questions get a vet, not a guess ----------
const MEDICAL = /\b(paracetamol|ibuprofen|aspirin|calpol|piriton|benadryl|antihistamines?|antibiotics?|painkillers?|pain ?killers?|dosage|doses?|(can|should|could) i give|vomit(s|ing|ed)?|being sick|diarrh(o)?ea|limping|lame(ness)?|lumps?|rash|itch(ing|y)?|scratching|not eating|off (his|her|its|their) food|letharg\w*|blood in|coughing|sneezing|discharge|swelling|swollen|weight loss|drinking (a lot|more)|diagnos\w*|symptoms?|infection|infected)\b|\bhow (much|many)\b.{0,30}\b(tablets?|pills?|ml|mg|medicine|medication)\b/i;
const consult = types.find((t) => /consult|check|exam/i.test(t.name));
const MEDICAL_REPLY = () => btns(to, 'I cannot give medical advice over WhatsApp - I would hate to get it wrong. '
  + 'A vet can take a proper look' + (pets.length === 1 ? ' at ' + pets[0].name : '') + '.\n\nIf it is urgent, call us on '
  + S(CFG.clinic_phone || CFG.emergency_phone) + '.',
  [consult ? { id: 'type:' + consult.id, title: 'Book a vet visit' } : { id: 'm:book', title: 'Book a vet visit' },
   { id: 'm:human', title: 'Talk to the team' }]);

// ---------- 3. commands that work from anywhere ----------
const menuRows = () => {
  const rows = [
    { id: 'm:book', title: 'Book an appointment', description: 'See real availability' },
    { id: 'm:ask', title: 'Ask a question', description: 'Prices, opening hours, what to bring' },
    { id: 'm:pets', title: 'My pets & reminders', description: 'Vaccinations due and bookings' },
    { id: 'm:human', title: 'Talk to the team', description: 'A person will reply here' },
  ];
  if (upcoming.length) rows.push({ id: 'm:cancel', title: 'Cancel an appointment', description: upcoming.length + ' booked' });
  return rows;
};
const showMenu = (lead) => done({ seen: state.seen, step: 'menu' },
  lst(to, (lead || hello + 'Welcome to ' + ctx.clinic + '.') + '\n\nHow can I help?', 'Options', 'How can I help?', menuRows()));

if (input.kind === 'text' && /^(menu|hi|hello|hey|start|help|options|salam|good (morning|afternoon|evening))[!. ]*$/i.test(low)) return showMenu();

if ((input.kind === 'text' && /^(stop|unsubscribe|stop reminders|no more reminders)[!. ]*$/i.test(low)) || input.id === 'stop_reminders') {
  const writes = owner ? [{ op: 'update', tab: 'Owners', row: owner.__row, record: { ...owner, reminders_opt_out: 'yes' } }] : [];
  return done({ seen: state.seen, step: 'menu' },
    txt(to, 'Done - no more vaccination reminders from us. You can still message here any time. Reply MENU for options.'), writes);
}

// ---------- 4. a "Book now" tap on a reminder jumps straight into booking ----------
function startBooking(st) {
  if (!owner) return done({ ...st, step: 'reg_name' }, txt(to, hello + 'Let us get you booked in. First, what is your name?'));
  if (!pets.length) return done({ ...st, step: 'reg_pet' }, txt(to, 'Lovely. What is your pet\'s name?'));
  if (st.petId && !st.typeId) return askType(st);
  if (st.petId && st.typeId) return needSlots(st);
  const rows = pets.map((p) => ({ id: 'pet:' + p.pet_id, title: p.name, description: [p.species, p.breed].filter(Boolean).join(', ') }))
    .concat([{ id: 'pet:new', title: 'Someone new', description: 'Add another pet' }]);
  return done({ ...st, step: 'pick_pet' }, lst(to, 'Who is the appointment for?', 'Choose pet', 'Your pets', rows));
}
function askType(st) {
  if (!types.length) return done({ ...st, step: 'menu' }, txt(to, 'Online booking is not set up yet - please call us on ' + S(CFG.clinic_phone) + '.'));
  const rows = types.map((t) => ({ id: 'type:' + t.id, title: t.name, description: [S(t.minutes) + ' min', t.price ? t.price : ''].filter(Boolean).join(' \u00b7 ') }));
  return done({ ...st, step: 'pick_type', page: 0 }, lst(to, 'What is ' + (st.petName || 'the appointment') + ' coming in for?',
    'Choose', 'Appointment types', paged(rows, 0)));
}
function needSlots(st) {
  const until = now.plus({ days: Number(CFG.booking_days) || 14 }).endOf('day');
  return [{ json: { action: 'slots', ctx, state: { ...st, step: 'loading_slots' },
    freeBusyBody: { timeMin: now.toUTC().toISO(), timeMax: until.toUTC().toISO(), timeZone: zone, items: [{ id: CFG.calendar_id }] } } }];
}

const bookPayload = input.id.match(/^book:([^:]*):?(.*)$/);
if (bookPayload) {
  const pet = pets.find((p) => p.pet_id === bookPayload[1]);
  const type = types.find((t) => t.id === bookPayload[2]) || types.find((t) => /vacc/i.test(t.name));
  const st = { seen: state.seen };
  if (pet) { st.petId = pet.pet_id; st.petName = pet.name; }
  if (type) { st.typeId = type.id; st.typeName = type.name; st.minutes = Number(type.minutes) || 15; }
  return startBooking(st);
}

// ---------- 5. emergency first, medical second, then the menu choices ----------
// Not while they are mid-booking (a pet can be called Lumpy), and not in a hand-off,
// where describing symptoms to the team is exactly the point.
const inFlow = /^(reg_|pick_|confirm|cancel_|handoff|loading)/.test(S(state.step));
if (input.kind === 'text' && !inFlow && MEDICAL.test(low)) {
  return done({ seen: state.seen, step: 'menu' }, MEDICAL_REPLY());
}
// typed numbers work on the menu too
if (input.kind === 'text' && /^[1-5]$/.test(low) && (!state.step || state.step === 'menu')) {
  const row = menuRows()[parseInt(low, 10) - 1];
  if (row) { input.kind = 'choice'; input.id = row.id; }
}

if (input.id === 'm:book') return startBooking({ seen: state.seen });
if (input.id === 'm:human' || (input.kind === 'text' && /^(talk to (a )?(human|person|someone|the team)|agent|human|speak to someone)[!. ]*$/i.test(low))) {
  const h = { handoff_id: newId('H'), phone: '+' + phone, name: (owner && owner.name) || m.profile_name,
    reason: 'Asked for a person', message: '', priority: 'normal', status: 'open', created_at: now.toISO() };
  // no quiet-period stamps yet: the next message is their actual question, so it is
  // acknowledged and sent to staff; only the ones after that are rate-limited
  return done({ seen: state.seen, step: 'handoff', handoffId: h.handoff_id },
    txt(to, 'No problem - a member of the team will reply here shortly (' + S(CFG.team_hours || 'during opening hours') + ').\n\nTell me anything you would like them to know.'),
    [{ op: 'append', tab: 'Handoffs', record: h }], { title: 'WhatsApp: ' + (h.name || '+' + phone) + ' wants a person', message: '+' + phone, priority: 0 });
}
if (input.id === 'm:ask') return done({ seen: state.seen, step: 'ask' }, txt(to, 'Sure - what would you like to know? (Prices, opening hours, what to bring, and so on.)'));
if (input.id === 'm:pets') {
  if (!pets.length) return done({ seen: state.seen, step: 'menu' }, txt(to, 'I do not have any pets on file for this number yet. Reply MENU and choose "Book an appointment" to add one.'));
  const months = Number(CFG.vaccination_interval_months) || 12;
  const lines = pets.map((p) => {
    const nextDue = parseDate(p.next_vaccination_due, CFG.date_order, zone)
      || (parseDate(p.last_vaccination, CFG.date_order, zone) ? parseDate(p.last_vaccination, CFG.date_order, zone).plus({ months }) : null);
    const appt = upcoming.find((a) => a.pet_id === p.pet_id);
    return '\u2022 ' + p.name + (p.species ? ' (' + p.species + ')' : '') + '\n   Vaccination due: '
      + (nextDue ? nextDue.toFormat('d LLL yyyy') + (nextDue < now ? ' - overdue' : '') : 'not on file')
      + (appt ? '\n   Booked: ' + S(appt.type) + ', ' + DateTime.fromISO(appt.start, { zone }).toFormat('ccc d LLL, HH:mm') : '');
  });
  return done({ seen: state.seen, step: 'menu' }, txt(to, 'Here is what I have:\n\n' + lines.join('\n\n') + '\n\nReply MENU to book.'));
}
if (input.id === 'm:cancel' || (input.kind === 'text' && /^cancel( (my )?(appointment|booking))?[!. ]*$/i.test(low))) {
  if (!upcoming.length) return done({ seen: state.seen, step: 'menu' }, txt(to, 'You have no upcoming appointments with us. Reply MENU for options.'));
  const a = upcoming[0];
  const when = DateTime.fromISO(a.start, { zone }).toFormat('cccc d LLLL \u00b7 HH:mm');
  return done({ seen: state.seen, step: 'cancel_confirm', apptId: a.appt_id },
    btns(to, 'Cancel this appointment?\n\n\u2022 ' + S(a.type) + ' for ' + S(a.pet_name) + '\n\u2022 ' + when,
      [{ id: 'cx:yes', title: 'Yes, cancel it' }, { id: 'cx:no', title: 'No, keep it' }]));
}

// ---------- 6. the step we are in ----------
const pick = (opts) => {
  if (input.kind === 'choice') return opts.find((o) => o.id === input.id) || null;
  if (input.kind !== 'text' || !low) return null;
  if (/^\d{1,2}$/.test(low)) return opts.filter((o) => !o.id.startsWith('__'))[parseInt(low, 10) - 1] || null;
  return opts.find((o) => S(o.title).toLowerCase() === low) || opts.find((o) => low.length >= 3 && S(o.title).toLowerCase().includes(low)) || null;
};

switch (state.step) {
  case 'reg_name': {
    if (input.kind !== 'text' || input.text.length < 2 || input.text.length > 60) return done(state, txt(to, 'Please type your name.'));
    return done({ ...state, step: 'reg_pet', ownerName: input.text.replace(/\s+/g, ' ') }, txt(to, 'Thanks ' + input.text.split(' ')[0] + '. And your pet\'s name?'));
  }
  case 'reg_pet': {
    if (input.kind !== 'text' || input.text.length < 1 || input.text.length > 40) return done(state, txt(to, 'Please type your pet\'s name.'));
    return done({ ...state, step: 'reg_species', petName: input.text.replace(/\s+/g, ' ') },
      btns(to, 'Is ' + input.text + ' a dog, a cat, or something else?',
        [{ id: 'sp:Dog', title: 'Dog' }, { id: 'sp:Cat', title: 'Cat' }, { id: 'sp:Other', title: 'Something else' }]));
  }
  case 'reg_species': {
    const opts = [{ id: 'sp:Dog', title: 'Dog' }, { id: 'sp:Cat', title: 'Cat' }, { id: 'sp:Other', title: 'Something else' }];
    const opt = pick(opts) || (input.kind === 'text' && input.text.length >= 3 ? { id: 'sp:' + input.text.slice(0, 30), title: input.text } : null);
    if (!opt) return done(state, btns(to, 'Please tap one:', opts));
    const species = opt.id.slice(3) === 'Other' ? 'Other' : opt.id.slice(3);
    const writes = [];
    if (!owner) writes.push({ op: 'append', tab: 'Owners', record: { owner_id: newId('O'), phone: '+' + phone,
      name: S(state.ownerName) || m.profile_name, email: '', reminders_opt_out: 'no', created_at: now.toISO() } });
    const petId = newId('P');
    writes.push({ op: 'append', tab: 'Pets', record: { pet_id: petId, owner_phone: '+' + phone, name: state.petName,
      species, breed: '', dob: '', last_vaccination: '', next_vaccination_due: '', notes: 'Added via WhatsApp', created_at: now.toISO() } });
    const st = { ...state, petId, species };
    ctx.pendingWrites = writes;               // saved with whichever step answers next
    return st.typeId ? needSlots(st) : askType(st);
  }
  case 'pick_pet': {
    const rows = pets.map((p) => ({ id: 'pet:' + p.pet_id, title: p.name })).concat([{ id: 'pet:new', title: 'Someone new' }]);
    const opt = pick(rows);
    if (!opt) return startBooking({ seen: state.seen });
    if (opt.id === 'pet:new') return done({ seen: state.seen, step: 'reg_pet' }, txt(to, 'What is your new pet\'s name?'));
    const pet = pets.find((p) => 'pet:' + p.pet_id === opt.id);
    return askType({ seen: state.seen, petId: pet.pet_id, petName: pet.name, species: pet.species });
  }
  case 'pick_type': {
    const rows = types.map((t) => ({ id: 'type:' + t.id, title: t.name }));
    if (input.id === '__more' || input.id === '__first') {
      const page = input.id === '__more' ? (state.page || 0) + 1 : 0;
      const full = types.map((t) => ({ id: 'type:' + t.id, title: t.name, description: S(t.minutes) + ' min' }));
      return done({ ...state, page }, lst(to, 'More appointment types:', 'Choose', 'Appointment types', paged(full, page)));
    }
    const opt = pick(rows);
    if (!opt) return askType(state);
    const t = types.find((x) => 'type:' + x.id === opt.id);
    return needSlots({ ...state, typeId: t.id, typeName: t.name, minutes: Number(t.minutes) || 15 });
  }
  case 'pick_day': {
    const days = (state.days || []).map((d) => ({ id: 'day:' + d.iso, title: d.label, iso: d.iso }));
    const opt = pick(days);
    if (!opt) return done(state, lst(to, 'Please choose a day:', 'Choose day', 'Available days', days.map((d) => ({ id: d.id, title: d.title }))));
    const times = ((state.slots || {})[opt.iso] || []).map((t) => ({ id: 'tm:' + t, title: t }));
    if (!times.length) return needSlots(state);                    // the cache emptied: look again
    return done({ ...state, step: 'pick_time', dayISO: opt.iso, dayLabel: opt.title, page: 0 },
      lst(to, 'Times free on ' + opt.title + ':', 'Choose time', opt.title, paged(times, 0)));
  }
  case 'pick_time': {
    const times = ((state.slots || {})[state.dayISO] || []).map((t) => ({ id: 'tm:' + t, title: t }));
    if (input.id === '__more' || input.id === '__first') {
      const page = input.id === '__more' ? (state.page || 0) + 1 : 0;
      return done({ ...state, page }, lst(to, 'More times on ' + state.dayLabel + ':', 'Choose time', S(state.dayLabel), paged(times, page)));
    }
    let opt = pick(times);
    if (!opt && input.kind === 'text') {
      const mm = low.replace(/[.\s]/g, ':').match(/^(\d{1,2}):?(\d{2})?$/);
      if (mm) opt = times.find((t) => t.title === String(mm[1]).padStart(2, '0') + ':' + (mm[2] || '00')) || null;
    }
    if (!opt) return done(state, lst(to, 'Please choose a time on ' + state.dayLabel + ':', 'Choose time', S(state.dayLabel), paged(times, state.page || 0)));
    const st = { ...state, step: 'confirm', time: opt.title };
    return done(st, btns(to, 'Please check:\n\n\u2022 ' + state.typeName + ' for ' + state.petName + '\n\u2022 ' + state.dayLabel + ' at ' + opt.title
      + '\n\u2022 ' + (state.minutes || 15) + ' minutes\n\nShall I book it?',
      [{ id: 'ok', title: 'Confirm' }, { id: 'change', title: 'Change time' }, { id: 'restart', title: 'Start over' }]));
  }
  case 'confirm': {
    if (input.id === 'restart') return showMenu('No problem, starting again.');
    if (input.id === 'change') {
      const times = ((state.slots || {})[state.dayISO] || []).map((t) => ({ id: 'tm:' + t, title: t }));
      return done({ ...state, step: 'pick_time', page: 0 }, lst(to, 'Pick another time on ' + state.dayLabel + ':', 'Choose time', S(state.dayLabel), paged(times, 0)));
    }
    if (input.id !== 'ok' && !(input.kind === 'text' && /^(yes|y|ok|confirm|book it|yes please)[!. ]*$/i.test(low))) {
      return done(state, btns(to, 'Shall I book ' + state.dayLabel + ' at ' + state.time + '?',
        [{ id: 'ok', title: 'Confirm' }, { id: 'change', title: 'Change time' }, { id: 'restart', title: 'Start over' }]));
    }
    const day = DateTime.fromISO(state.dayISO, { zone });
    return [{ json: { action: 'book', ctx, state,
      freeBusyBody: { timeMin: day.startOf('day').toUTC().toISO(), timeMax: day.endOf('day').toUTC().toISO(), timeZone: zone, items: [{ id: CFG.calendar_id }] } } }];
  }
  case 'cancel_confirm': {
    const appt = T.Appointments.rows.find((a) => a.appt_id === state.apptId && digits(a.owner_phone) === phone);
    if (input.id === 'cx:no' || (input.kind === 'text' && /^(no|n|keep( it)?)[!. ]*$/i.test(low))) return showMenu('No problem, it is still booked.');
    if (input.id !== 'cx:yes' && !(input.kind === 'text' && /^(yes|y)[!. ]*$/i.test(low))) {
      return done(state, btns(to, 'Cancel it - yes or no?', [{ id: 'cx:yes', title: 'Yes, cancel it' }, { id: 'cx:no', title: 'No, keep it' }]));
    }
    if (!appt) return showMenu('I could not find that appointment any more.');
    return [{ json: { action: 'cancel', ctx, state: { seen: state.seen, step: 'menu' }, appt,
      eventUrl: 'https://www.googleapis.com/calendar/v3/calendars/' + encodeURIComponent(CFG.calendar_id) + '/events/' + encodeURIComponent(S(appt.calendar_event_id)) } }];
  }
  case 'handoff': {
    // Staff may be mid-conversation with them. Record every message, but acknowledge at
    // most every 30 minutes and buzz the staff phone at most every 10.
    const t = now.toMillis();
    const ackNow = !state.lastAck || t - state.lastAck >= 30 * 60000;
    const alertNow = !state.lastAlert || t - state.lastAlert >= 10 * 60000;
    const st = { ...state, lastAck: ackNow ? t : state.lastAck, lastAlert: alertNow ? t : state.lastAlert };
    const text = input.kind === 'text' ? input.text : '[' + (input.text || m.kind || 'attachment') + ']';
    const h = { handoff_id: newId('H'), phone: '+' + phone, name: (owner && owner.name) || m.profile_name,
      reason: 'Follow-up to ' + S(state.handoffId), message: S(text).slice(0, 500), priority: 'normal', status: 'open', created_at: now.toISO() };
    return done(st, ackNow ? txt(to, 'Thanks - I have passed that on. The team will reply here.') : null,
      [{ op: 'append', tab: 'Handoffs', record: h }],
      alertNow ? { title: 'WhatsApp follow-up from ' + (h.name || '+' + phone), message: S(text).slice(0, 300), priority: 0 } : null);
  }
  default: break;                                          // menu, ask, or nothing yet
}

// ---------- 7. anything else is a question for the FAQ ----------
if (input.kind !== 'text' || input.text.length < 3) return showMenu();
if (!faq.length) return done({ seen: state.seen, step: 'menu' }, txt(to, 'I cannot answer questions yet - reply MENU and choose "Talk to the team".'));

// No vector database needed for a clinic's FAQ: score entries by shared words, send the best.
const STOP = new Set('a an the is are do does you your i my me we our can how what when where which who for of to in on at it and or be with about have has any'.split(' '));
const words = (s) => S(s).toLowerCase().replace(/[^a-z0-9\u00a3\u20ac$ ]/g, ' ').split(/\s+/).filter((w) => w.length > 2 && !STOP.has(w));
const qw = new Set(words(input.text));
const scored = faq.map((f) => {
  const fw = words(f.question + ' ' + f.tags + ' ' + f.answer);
  let score = 0; for (const w of fw) if (qw.has(w)) score += 1;
  for (const w of words(f.question + ' ' + f.tags)) if (qw.has(w)) score += 2;          // question and tags count more
  return { f, score };
}).sort((a, b) => b.score - a.score);
const picked = (faq.length <= 12 ? faq.map((f) => ({ f, score: 1 })) : scored.slice(0, 12)).map((x) => x.f);

const faqPrompt = 'Customer question: ' + input.text.slice(0, 600) + '\n\nClinic FAQ entries:\n'
  + picked.map((f) => '[' + f.id + '] Q: ' + f.question + '\nA: ' + f.answer).join('\n\n');
return [{ json: { action: 'ai', ctx, state: { seen: state.seen, step: 'menu' }, question: input.text.slice(0, 600),
  faqPrompt, faqIds: picked.map((f) => f.id), faqAnswers: Object.fromEntries(picked.map((f) => [f.id, f.answer])) } }];

// ===== Outcome =====
// Every branch of the conversation ends here. Last check before anything is sent or saved.
const out = [];
// A problem must never hide behind another alert: fold it into whatever is already going out.
const merge = (alert, title, message) => (alert
  ? { ...alert, title: alert.title + ' (+ ' + title.toLowerCase() + ')', message: alert.message + '\n' + title + ': ' + message }
  : { title, message, priority: 0 });
for (const it of $input.all()) {
  const o = { ...it.json };
  const known = o.headers || {};
  const quiet = o.silent === true && o.reply === null;           // deliberate: staff are handling it
  if (!quiet && (!o.reply || o.reply.messaging_product !== 'whatsapp')) {
    o.reply = { messaging_product: 'whatsapp', recipient_type: 'individual', to: String(o.to || ''), type: 'text',
      text: { preview_url: false, body: 'Sorry, something went wrong on our side. Reply MENU to try again.' } };
    o.alert = merge(o.alert, 'Bot produced no reply', '+' + o.to);
  }
  // drop anything aimed at a tab we have no header for, rather than writing a misaligned row
  const dropped = (o.writes || []).filter((w) => !(w && w.tab && known[w.tab] && known[w.tab].length
    && (w.op === 'append' || (w.op === 'update' && Number(w.row) >= 2))));
  o.writes = (o.writes || []).filter((w) => !dropped.includes(w));
  if (dropped.length) o.alert = merge(o.alert, 'Sheet write skipped',
    dropped.map((w) => (w && w.tab) || '?').join(', ') + ' - check the tab and its header row');
  out.push({ json: o });
}
return out;

// ===== Use Availability =====
// Turns Google Calendar's busy blocks into bookable times. Used twice: to list the
// days that have space, and to re-check the exact slot seconds before booking it.
const CFG = $('Config').first().json;
const E = $('Assistant Engine').first().json;
const ctx = E.ctx;
const fb = $input.first().json || {};
// --- Google Sheets helpers (identical copy in every node that reads the sheet) ---
const S = (v) => (v == null ? '' : String(v));
const digits = (s) => S(s).replace(/\D/g, '');

// values:batchGet returns ragged rows: trailing empty cells are simply missing, and a
// blank line comes back as []. Read by header name and keep the real sheet row number.
function readTables(batch, names) {
  const out = {};
  const vrs = (batch && batch.valueRanges) || [];
  names.forEach((name, i) => {
    const vr = vrs[i] || {};
    const got = S(vr.range).replace(/^'|'?!.*$/g, '');
    if (vr.range && got && got !== name) throw new Error('Sheet order mismatch: expected ' + name + ', got ' + got);
    const rows = vr.values || [];
    const header = (rows[0] || []).map((h) => S(h).trim());
    const recs = [];
    for (let r = 1; r < rows.length; r++) {
      const row = rows[r] || [];
      if (!row.some((c) => S(c).trim() !== '')) continue;
      const rec = { __row: r + 1 };
      header.forEach((h, c) => { if (h) rec[h] = row[c] === undefined ? '' : S(row[c]).trim(); });
      recs.push(rec);
    }
    out[name] = { header, rows: recs };
  });
  return out;
}

// Staff type dates however they like, and Sheets displays them in the sheet's locale.
function parseDate(raw, order, zone) {
  const v = S(raw).trim();
  if (!v) return null;
  let d = null;
  if (/^\d{4}-\d{2}-\d{2}/.test(v)) d = DateTime.fromISO(v.slice(0, 10), { zone });
  else if (/^\d{4,5}(\.\d+)?$/.test(v)) {                          // a raw Sheets serial number
    d = DateTime.fromISO('1899-12-30', { zone }).plus({ days: Math.floor(Number(v)) });
  } else {
    const m = v.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/);
    if (m) {
      const a = +m[1], b = +m[2]; let y = +m[3]; if (y < 100) y += 2000;
      const [day, month] = order === 'MDY' ? [b, a] : [a, b];
      d = DateTime.fromObject({ year: y, month, day }, { zone });
    } else {
      for (const f of ['d LLL yyyy', 'd LLLL yyyy', 'LLL d, yyyy', 'LLLL d, yyyy', 'd-LLL-yyyy']) {
        const t = DateTime.fromFormat(v, f, { zone });
        if (t.isValid) { d = t; break; }
      }
    }
  }
  return d && d.isValid ? d.startOf('day') : null;
}
// --- outcome helpers (identical copy in every node that ends a turn) ---
const clip = (s, n) => (S(s).length > n ? S(s).slice(0, n - 1) + '\u2026' : S(s));
const waBase = (to) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to });
const txt = (to, body) => ({ ...waBase(to), type: 'text', text: { preview_url: false, body: clip(body, 4096) } });
const btns = (to, body, opts) => ({ ...waBase(to), type: 'interactive',
  interactive: { type: 'button', body: { text: clip(body, 1024) },
    action: { buttons: opts.slice(0, 3).map((o) => ({ type: 'reply', reply: { id: clip(o.id, 256), title: clip(o.title, 20) } })) } } });
const lst = (to, body, buttonText, section, rows) => ({ ...waBase(to), type: 'interactive',
  interactive: { type: 'list', body: { text: clip(body, 1024) },
    action: { button: clip(buttonText, 20), sections: [{ title: clip(section, 24),
      rows: rows.slice(0, 10).map((r) => { const o = { id: clip(r.id, 200), title: clip(r.title, 24) };
        if (r.description) o.description = clip(r.description, 72); return o; }) }] } } });
// a list holds ten rows; longer option sets get a "More" row and a page number
function paged(options, page) {
  if (options.length <= 10) return options;
  const start = (page || 0) * 9;
  const rows = options.slice(start, start + 9);
  if (start + 9 < options.length) rows.push({ id: '__more', title: 'More \u25b8', description: 'Show more options' });
  else rows.push({ id: '__first', title: '\u25c2 Back to start', description: 'Show the first options' });
  return rows;
}
// every turn ends here: the reply, the session save, any other sheet writes, any staff alert
function outcome(ctx, state, reply, writes, alert) {
  let saved = JSON.stringify(state || {});
  if (saved.length > 40000 && state && state.slots) {           // a Sheets cell holds 50,000 characters
    saved = JSON.stringify({ ...state, slots: state.dayISO ? { [state.dayISO]: state.slots[state.dayISO] } : {} });
  }
  const sess = { phone: '+' + ctx.phone, state: saved, updated_at: DateTime.now().toUTC().toISO() };
  const first = ctx.sessionRow ? { op: 'update', tab: 'Sessions', row: ctx.sessionRow, record: sess }
                               : { op: 'append', tab: 'Sessions', record: sess };
  return { json: { outcome: true, to: ctx.phone, phone_number_id: ctx.phone_number_id,
    graph_version: ctx.graph_version, token: ctx.token, sheet_id: ctx.sheet_id, headers: ctx.headers,
    reply, silent: reply === null, writes: [first].concat(ctx.pendingWrites || [], writes || []), alert: alert || null } };
}
const zone = ctx.zone;
const now = DateTime.now().setZone(zone);
const to = ctx.phone;
let state = { ...(E.state || {}) };

// ---- what the calendar says ----
const cal = ((fb.calendars || {})[CFG.calendar_id]) || null;
const calError = fb.error || !cal || (cal.errors && cal.errors.length);
if (calError) {
  return [outcome(ctx, { seen: state.seen, step: 'menu' },
    txt(to, 'Sorry - I cannot see the diary right now. Please call us on ' + S(CFG.clinic_phone) + ' and we will book you in.'),
    [], { title: 'Booking diary unreachable', message: JSON.stringify(fb.error || (cal && cal.errors) || 'no calendar in response').slice(0, 300), priority: 0 })];
}
const busy = (cal.busy || []).map((b) => ({ s: DateTime.fromISO(b.start).setZone(zone), e: DateTime.fromISO(b.end).setZone(zone) }))
  .filter((b) => b.s.isValid && b.e.isValid);

// ---- opening hours: {"1":["08:30-12:30","13:30-18:00"], ...}, 0 = Sunday ----
let hours = {};
try { hours = typeof CFG.opening_hours === 'string' ? JSON.parse(CFG.opening_hours) : (CFG.opening_hours || {}); } catch (e) { hours = {}; }
const step = Number(CFG.slot_step_min) || 15;
const notice = Number(CFG.min_notice_min) || 60;
const buffer = Number(CFG.buffer_min) || 0;
const minutes = Number(state.minutes) || 15;

function freeSlots(dayISO) {
  const day = DateTime.fromISO(dayISO, { zone });
  const spans = hours[String(day.weekday % 7)] || [];
  const earliest = now.plus({ minutes: notice });
  const out = [];
  for (const span of spans) {
    const mt = String(span).match(/^(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})$/);
    if (!mt) continue;
    const open = day.set({ hour: +mt[1], minute: +mt[2], second: 0, millisecond: 0 });
    const close = day.set({ hour: +mt[3], minute: +mt[4], second: 0, millisecond: 0 });
    for (let t = open; t.plus({ minutes }) <= close; t = t.plus({ minutes: step })) {
      if (t < earliest) continue;
      const a = t.minus({ minutes: buffer }), b = t.plus({ minutes: minutes + buffer });
      if (busy.some((x) => a < x.e && b > x.s)) continue;              // half-open overlap
      out.push(t.toFormat('HH:mm'));
    }
  }
  return out;
}

// ---- list the days that have space ----
if (E.action === 'slots') {
  const days = []; const slots = {};
  const horizon = Number(CFG.booking_days) || 14;
  for (let i = 0; i <= horizon && days.length < 10; i++) {
    const d = now.plus({ days: i });
    const iso = d.toISODate();
    const free = freeSlots(iso);
    if (!free.length) continue;
    slots[iso] = free;
    days.push({ iso, label: i === 0 ? 'Today ' + d.toFormat('d LLL') : i === 1 ? 'Tomorrow ' + d.toFormat('d LLL') : d.toFormat('ccc d LLL'), count: free.length });
  }
  if (!days.length) {
    return [outcome(ctx, { seen: state.seen, step: 'menu' },
      txt(to, 'Sorry - we are fully booked for ' + (state.typeName || 'that') + ' over the next ' + horizon + ' days. Please call us on '
        + S(CFG.clinic_phone) + ' and we will try to fit you in.'))];
  }
  state = { ...state, step: 'pick_day', days, slots, page: 0 };
  return [outcome(ctx, state, lst(to, 'Which day suits ' + (state.petName || 'you') + '?', 'Choose day', 'Days with space',
    days.map((d) => ({ id: 'day:' + d.iso, title: d.label, description: d.count + (d.count === 1 ? ' time free' : ' times free') }))))];
}

// ---- re-check one slot just before booking it ----
const fresh = freeSlots(state.dayISO);
if (!fresh.includes(state.time)) {
  const slots = { ...(state.slots || {}), [state.dayISO]: fresh };
  if (!fresh.length) {
    const days = (state.days || []).filter((d) => d.iso !== state.dayISO);
    delete slots[state.dayISO];
    state = { ...state, step: 'pick_day', days, slots };
    return [outcome(ctx, state, days.length
      ? lst(to, 'Sorry - ' + state.dayLabel + ' has just filled up. Another day?', 'Choose day', 'Days with space',
          days.map((d) => ({ id: 'day:' + d.iso, title: d.label })))
      : txt(to, 'Sorry - that day has just filled up. Reply MENU to look again.'))];
  }
  state = { ...state, step: 'pick_time', slots, page: 0 };
  return [outcome(ctx, state, lst(to, 'Sorry - ' + state.time + ' was just taken. These are still free on ' + state.dayLabel + ':',
    'Choose time', S(state.dayLabel), paged(fresh.map((t) => ({ id: 'tm:' + t, title: t })), 0)))];
}

const start = DateTime.fromISO(state.dayISO + 'T' + state.time, { zone });
const end = start.plus({ minutes });
const apptId = 'A-' + Math.random().toString(36).slice(2, 8).toUpperCase();
const ownerName = S((ctx.owner && ctx.owner.name) || state.ownerName);
return [{ json: {
  createEvent: true, apptId, start: start.toISO({ suppressMilliseconds: true }), end: end.toISO({ suppressMilliseconds: true }),
  eventUrl: 'https://www.googleapis.com/calendar/v3/calendars/' + encodeURIComponent(CFG.calendar_id) + '/events',
  eventBody: {
    summary: S(state.typeName) + ' - ' + S(state.petName) + (state.species ? ' (' + state.species + ')' : '') + ' - ' + (ownerName || '+' + to),
    description: 'Booked via WhatsApp\nOwner: ' + (ownerName || 'unknown') + ' (+' + to + ')\nPet: ' + S(state.petName)
      + (state.species ? ', ' + state.species : '') + '\nRef: ' + apptId,
    start: { dateTime: start.toISO({ suppressMilliseconds: true }), timeZone: zone },
    end: { dateTime: end.toISO({ suppressMilliseconds: true }), timeZone: zone },
    extendedProperties: { private: { source: 'whatsapp', phone: to, pet_id: S(state.petId), appt_id: apptId } },
  },
} }];

