// ===== Split Writes =====
// Row updates go in one batchUpdate call. New rows each use values:append, because
// Google picks the next free row itself - two customers at once can never overwrite
// each other, which a computed "next row" number cannot promise.
// RAW means nothing a customer types is ever treated as a formula.
const out = [];
const S = (v) => (v == null ? '' : String(v));
const col = (n) => { let s = ''; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const q = (t) => (/^[A-Za-z0-9_]+$/.test(t) ? t : "'" + t.replace(/'/g, "''") + "'");
for (const it of $input.all()) {
  const o = it.json;
  if (!o.sheet_id) continue;
  const base = 'https://sheets.googleapis.com/v4/spreadsheets/' + encodeURIComponent(o.sheet_id);
  const updates = [];
  for (const w of (o.writes || [])) {
    const header = (o.headers || {})[w.tab] || [];
    if (!header.length) continue;
    const values = header.map((h) => (h ? S(w.record && w.record[h] !== undefined ? w.record[h] : '').slice(0, 49000) : ''));
    if (w.op === 'update' && Number(w.row) >= 2) {
      // Only touch columns that have a header. A column someone added without one
      // holds notes we know nothing about, and blanking it would lose them.
      let i = 0;
      while (i < header.length) {
        if (!header[i]) { i++; continue; }
        let j = i;
        while (j + 1 < header.length && header[j + 1]) j++;
        updates.push({ range: q(w.tab) + '!' + col(i + 1) + w.row + ':' + col(j + 1) + w.row, values: [values.slice(i, j + 1)] });
        i = j + 1;
      }
    } else if (w.op === 'append') {
      out.push({ json: { method: 'POST',
        url: base + '/values/' + encodeURIComponent(q(w.tab) + '!A1') + ':append?valueInputOption=RAW&insertDataOption=INSERT_ROWS',
        body: { values: [values] }, tab: w.tab, op: 'append' } });
    }
  }
  if (updates.length) out.unshift({ json: { method: 'POST', url: base + '/values:batchUpdate',
    body: { valueInputOption: 'RAW', data: updates }, tab: updates.map((u) => u.range.split('!')[0]).join(','), op: 'update' } });
}
return out;
